// TH14 v1.00b st05 wave: GirlC01 x10 (MainSub03) + ECir00 x20 (MainSub03b async).
// Sources: st05.ecl.txt:687-701 entry, 703-734 async schedule,
//          14-81 ECir00/ECir00_at, 230-320 GirlC01/GirlC01_at.
// Enemy presentation (anm*/drops/sounds) omitted per approved policy; collision,
// motion, emitters and the EX birth displacement are kept.

const TIME_LIMIT: int = 2724;
const OPENING_BUFFER: int = 120;

const COLOR_GIRL: int = 2;
const COLOR_ECIR: int = 6;

// Source etEx(0,0,4,120,-999999,0.033333335,F2-pi): vector ACCEL for 120 frames,
// literal direction F2-pi, then the acceleration is cleared and velocity kept.
xformdef ECIR_ACCEL(dir: angle) {
    set_gravity(0.0333333fx * cos(dir), 0.0333333fx * sin(dir));
    wait(120);
    set_gravity(0fx, 0fx);
}

// st05:703-734 MainSub03b. Batch 1 at y=200 (I0=1, F2=-90deg, F1 center -100),
// then wait 400, batch 2 at y=300 (I0=2, F2 alternating, F1 center -32).
async sub ecir_wave() {
    wait(200);
    var f0: fx = -160fx;
    var f1: fx = 0fx;
    for i in 0..10 {
        f0 = f0 + 32fx;
        f1 = (((rand(65536) - 32768) as fx) / 32768) * 32fx - 100fx;
        _ = spawn_enemy(0fx, 200fx, 160, 0, 0, 0, ecir_main(f0, f1, -16384, 1));
        wait(10);
    }
    wait(400);
    f0 = -160fx;
    var f2: int = -16384;
    for j in 0..10 {
        f0 = f0 + 32fx;
        f1 = (((rand(65536) - 32768) as fx) / 32768) * 32fx - 32fx;
        _ = spawn_enemy(0fx, 300fx, 160, 0, 0, 0, ecir_main(f0, f1, f2, 2));
        f2 = 0 - f2;
        wait(10);
    }
}

// st05:687-701 MainSub03: five rounds of left GirlC01 then mirrored GirlC01, 120 apart.
async sub girlc_wave() {
    for i in 0..5 {
        _ = spawn_enemy(-224fx, 128fx, 300, 0, 0, 0, girlc_main(0));
        wait(120);
        _ = spawn_enemy(224fx, 128fx, 300, 0, 0, 0, girlc_main(1));
        wait(120);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    spawn girlc_wave();
    spawn ecir_wave();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// st05:230-258 GirlC01. Source frame setHurtbox(24)/setHitbox(16) -> radii 12/8.
// Mirroring: plain moveVel/moveVelTime carry the native x mirror (angle -> pi-angle).
async sub girlc_main(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    var a_in: angle = 0deg;
    var a_turn: angle = -45deg;
    if mirror != 0 {
        a_in = 180deg;
        a_turn = 225deg;
    }
    move_vel(0, a_in, 1.5fx, EASE_LINEAR);
    move_vel(80, a_turn, 0.1fx, EASE_QUAD_IN);
    wait(60);
    // diffI(A,1,1,2,4)
    var rounds: int = 1;
    if global(GVAR_RANK) == RANK_HARD { rounds = 2; }
    else if global(GVAR_RANK) == RANK_LUNATIC { rounds = 4; }
    for i in 0..rounds {
        spawn girlc_at(mirror);
        wait(180);
    }
    move_vel(80, a_turn, 2fx, EASE_QUAD_IN);
    loop { wait(1000); }
}

// st05:260-320 GirlC01_at. 36 shots one frame apart. Per shot: one fixed angle
// (base aim-/+90deg, stepping -/+10deg) and two speed layers B and 1.0.
// etDist(16) minus ANIM birth shift 4*speed gives the per-bullet spawn distance.
async sub girlc_at(mirror: int) {
    var layers: int = 1;
    if global(GVAR_RANK) != RANK_EASY { layers = 2; }
    var f0: int = 16384;
    var df: int = 1820;
    if mirror != 0 {
        f0 = -16384;
        df = -1820;
    }
    var aim: int = atan2($player_y - $self_y, $player_x - $self_x) as int;
    var a: int = aim - f0;
    var b: fx = 3fx;
    for k in 0..36 {
        var ang: angle = a as angle;
        var d0: fx = 16fx - 4fx * b;
        _ = fire(TH14_OVAL, COLOR_GIRL, $self_x + d0 * cos(ang), $self_y + d0 * sin(ang), b, ang, none, none);
        if layers > 1 {
            var d1: fx = 16fx - 4fx;
            _ = fire(TH14_OVAL, COLOR_GIRL, $self_x + d1 * cos(ang), $self_y + d1 * sin(ang), 1fx, ang, none, none);
        }
        a = a + df;
        b = b - 0.05fx;
        wait(1);
    }
}

// st05:14-47 ECir00. Source flagSet(15)/flagClear(15) bracketing the intro keeps
// body contact off for 160 frames (0x2); 0x4/0x8 offscreen flags have no target
// counterpart. movePosRel then movePosRelTime(160,mode1,F0,F1) on the REL layer,
// with ABS held at the spawn point.
async sub ecir_main(f0: fx, f1: fx, f2: int, volleys: int) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    var y0: fx = $self_y;
    var rx: fx = 160fx + (((rand(65536) - 32768) as fx) / 32768) * 32fx;
    var ry: fx = (((rand(65536) - 32768) as fx) / 32768) * 64fx;
    move_to(0, rx, y0 + ry, EASE_LINEAR);
    move_to(160, f0, y0 + f1, EASE_QUAD_IN);
    wait(160);
    set_enemy_flag(ENEMY_NO_BODY, 0);
    spawn ecir_at(f2, volleys);
    wait(120);
    move_vel(0, atan2($player_y - $self_y, $player_x - $self_x), 0fx, EASE_LINEAR);
    move_speed(120, 3fx, EASE_LINEAR);
    loop { wait(1000); }
}

// st05:49-81 ECir00_at. Fixed-direction fan of 1/3/5/7 ways, speed 2, center F2
// plus one fresh +-10deg draw per volley, 4 frames apart, I0 volleys.
async sub ecir_at(f2: int, volleys: int) {
    wait(10);
    var ways: int = 1;
    if global(GVAR_RANK) == RANK_NORMAL { ways = 3; }
    else if global(GVAR_RANK) == RANK_HARD { ways = 5; }
    else if global(GVAR_RANK) == RANK_LUNATIC { ways = 7; }
    sh_reset(0);
    sh_sprite(0, TH14_SHARD, COLOR_ECIR);
    sh_ring(0, 0);
    sh_aim(0, 0);
    sh_count(0, ways, 1);
    sh_angle(0, f2 as angle, 10deg);
    sh_speed(0, 2fx, 0fx);
    sh_dist(0, -8fx);
    sh_xform(0, ECIR_ACCEL((f2 - 32768) as angle));
    for v in 0..volleys {
        var u: fx = ((rand(65536) - 32768) as fx) / 32768;
        var alpha: int = f2 + ((u * 1820fx) as int);
        sh_angle(0, alpha as angle, 10deg);
        sh_fire(0);
        wait(4);
    }
}
